      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9월~ ) 만20세~29세 1인가구 여성 ) 생활용품 유치 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.27. 15:07\n조회 66\n구독\n9월~ ) 만20세~29세 1인가구 여성 ) 생활용품 유치 조사\n현재 20~29세 1인가구.\n스O글 허O블 코튼, 허거블 선샤인 주 사용자만 신청해주세요~\n다O니 사용자 마감\n기본 조건\n만20세~29세 1인가구 여성\n댁 내 생활용품 구매 결정자\n조사 일정중 정해진 가이드에 따라 성실히 참여 해주실 분\n임신/수유중, 알러지, 호흡기 질환자는 참여 불가\n조사 일정\n9월1일~약 2주간, 보내 드리는 섬유유연제를 사용후 온라인 설문 참여\n9월1~20일 여행,출장등 집을 비우는 계획이 없으신 분\n조사 방법\n1.제품을 댁으로 발송해 드림\n2.정해진 가이드에 따라 제품 사용후 총 3번의 온라인 설문 ( 온라인 설문은 각 차수별 10분 소요)\n3. 조사 응답후 제품 발송해 주셔야 최종 완료\n( 회수가 되지 않거나, 분실시 사례비 지급하지 않습니다 )\n사례비\n3만5천원 ( 사용 후 제품 선불 발송비 포함)\n신청 시 기재사항\n성명/연락처/이메일/생년월일/거주지_ 동까지/혼인여부/직업/가족구성_유자녀는 자녀 나이 모두 / 1주 평균_ 세탁 횟수( 세탁기사용기준) / 1주평균_ 섬유유연제 사용 횟수 / 건조기 유무 / 현재 사용중인 섬유유연제 모두 / 주사용 섬유유연제 ( 브랜드+ 향_ 정확하게 기입)\n신청후 섬유 유연제 사진 (섬유유연제가 놓여진 장소 확인 가능하도록, 전체샷+ 제품 확대샷, 최소 2장이상)을 아래 링크에 올려주신 분들 우선적으로 연락 드리겠습니다\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://tally.so/r/ODx4ag\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.08.27. 15:45 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n9/7(월) 만 14~29세 남성) 아이스크림 조사\n좌담회알바좌담회카페\n26.08.27.\n댓글\n1\n9월~ ) 만20세~29세 1인가구 여성 ) 생활용품 유치 조사\n좌담회알바좌담회카페\n26.08.27.\n댓글\n1\n만나이 19~45세 여성 (2007~1980년생) 간식 맛 테스트 갱조사\n좌담회알바좌담회카페\n26.08.27.\n댓글\n1\n8~9월 중 일정 협의)30분3만) Zoom 또는 전화 인터뷰 -패션 브랜드 근무자 좌담회-20세 이상 여성\n좌담회알바좌담회카페\n26.08.27.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
